

def generate_thyroid_boundary_cases(n: int = 110) -> list[dict]:
    cases = []
    boundary_pairs = [
        ("3", "4a"), ("4a", "4b"), ("4b", "4c"), ("4", "5"),
    ]
    descriptions = {
        "2": "甲状腺囊性结节，边界清晰，形态规则，无钙化",
        "3": "甲状腺结节，边界尚清晰，形态尚规则，无微钙化",
        "4a": "甲状腺实性结节，边界欠清，低回声，无微钙化",
        "4b": "甲状腺实性结节，边界不清，低回声，微钙化可能",
        "4c": "甲状腺实性低回声结节，边界不清，微钙化，纵横比>1",
        "4": "甲状腺实性结节，边界不清，需进一步评估",
        "5": "甲状腺实性低回声结节，边界不清，微钙化，纵横比>1，丰富血流",
    }
    for i in range(n):
        from_g, to_g = boundary_pairs[i % len(boundary_pairs)]
        case = {
            "case_id": f"thyroid_boundary_{i+1:03d}",
            "organ": "thyroid",
            "prompt": f"请对以下甲状腺超声描述进行TI-RADS分级：{descriptions[from_g]}",
            "expected_grading": from_g,
            "engine_a_grading": from_g,
            "engine_b_grading": to_g,
            "is_boundary_case": True,
            "boundary_from": from_g,
            "boundary_to": to_g,
        }
        cases.append(case)
    return cases


